1	import { useMemo, type ReactNode } from "react";
2	import type { ChecklistItem, Pack } from "@runlog/rules-schema";
3	import type { RunState } from "@runlog/engine";
4	import { allMade, evidenceFor, pointMade, pointOf, rowMade, type Settling, type Shown } from "./evidence.ts";
5	
6	/**
7	 * Points to tick off, with their evidence under them.
8	 *
9	 * A point that shows a table's results lists them beneath it, each with a box
10	 * of its own; ticking them all ticks the point, and ticking the point ticks
11	 * them all. The parent's box is what the point reads as, the children are
12	 * what it is about. A point with nothing to show is a plain box.
13	 *
14	 * A point that shows a table the unit never rolled on is not shown at all:
15	 * there is nothing to make a promise about, and a box that must be ticked
16	 * beside "nothing on the table" is a box that teaches people to tick
17	 * without reading. An optional point is shown, and the step does not wait
18	 * for it. A point with a tally counts its ticks.
19	 *
20	 * The ticked set is the step's and lives in the log, so a reload keeps it.
21	 *
22	 * What the boxes are for used to be written out over every list: the app
23	 * cannot see the work, it only records that you did it. It is the premise
24	 * of the whole thing, said once in the guide and on the welcome page, and
25	 * printing it above every step read as a machine that did not trust the
26	 * person using it. The list carries it as its title instead, for whoever
27	 * wonders.
28	 */
29	export function Checklist({
30	  items,
31	  pack,
32	  state,
33	  ticked,
34	  onToggle,
35	  settling,
36	  action,
37	}: {
38	  items: ChecklistItem[];
39	  pack: Pack;
40	  state: RunState;
41	  ticked: Set<string>;
42	  onToggle: (keys: string[], on: boolean, tally?: string) => void;
43	  /** Which rows the game settles itself, and whether it has; see evidence.ts. */
44	  settling?: Settling;
45	  /** The move a row is waiting on, drawn on the row rather than in a panel of its own. */
46	  action?: (s: Shown) => ReactNode;
47	}) {
48	  const points = useMemo(() => items.map(pointOf), [items]);
49	  const evidence = useMemo(() => points.map((p) => (p.shows ? evidenceFor(pack, state, p.shows) : [])), [points, pack, state]);
50	
51	  return (
52	    <ul
53	      className="checklist"
54	      title="Nothing here is checked by the app. It cannot see the work; ticking a box is your word, and the log keeps it."
55	    >
56	      {points.map((point, i) => {
57	        const shown: Shown[] = evidence[i] ?? [];
58	        if (point.shows && shown.length === 0) return null;
59	        // What is already in front of the player as a rule is not listed
60	        // again under a box; a point with nothing left to list has nothing
61	        // to ask, and the rule it stands for is doing the asking.
62	        //
63	        // Only where something can actually answer it, though: the game
64	        // settling it, or the rule carrying the tick that honors it. A row
65	        // nothing can answer stays on the screen whatever it is told,
66	        // because the alternative is a step that cannot be finished.
67	        const answerable = (s: Shown) => Boolean(settling && (settling.owing(s) || settling.settled(s) || settling.answered?.(s)));
68	        const listed = shown.filter((s) => !(settling?.hidden?.(s) && answerable(s)));
69	        if (point.shows && listed.length === 0) return null;
70	        // A row the game settles is not offered as a box to tick, and
71	        // ticking the point over it does not reach down to it.
72	        const mine = listed.filter((s) => !settling?.owing(s) && !settling?.settled(s));
73	        const childKeys = mine.map((s) => `${i}:${s.key}`);
74	        const made = pointMade(i, shown, ticked, point, settling);
75	        const toggle = (keys: string[], on: boolean) =>
76	          onToggle(
77	            keys.filter((k) => ticked.has(k) !== on),
78	            on,
79	            point.tally,
80	          );
81	        return (
82	          <li key={i}>
83	            <label>
84	              <input
85	                type="checkbox"
86	                checked={made}
87	                disabled={listed.length > 0 && childKeys.length === 0}
88	                onChange={(e) => toggle(shown.length > 0 ? childKeys : [`${i}`], e.target.checked)}
89	              />
90	              <span>
91	                {point.text}
92	                {point.optional && <span className="chip skip">optional</span>}
93	              </span>
94	            </label>
95	            {listed.length > 0 && (
96	              <ul className="evidence">
97	                {listed.map((s) => {
98	                  const key = `${i}:${s.key}`;
99	                  const theirs = Boolean(settling?.owing(s) || settling?.settled(s));
100	                  return (
101	                    <li key={key} className={theirs ? "settling" : ""}>
102	                      <label>
103	                        <input
104	                          type="checkbox"
105	                          checked={rowMade(key, s, ticked, settling)}
106	                          disabled={theirs}
107	                          title={theirs ? "The game settles this one: it is honored by the roll it asks for, not by saying so." : undefined}
108	                          onChange={(e) => toggle([key], e.target.checked)}
109	                        />
110	                        <span>
111	                          <span className="where">{s.where}</span>
112	                          {s.text}
113	                        </span>
114	                      </label>
115	                      {settling?.owing(s) && action?.(s)}
116	                    </li>
117	                  );
118	                })}
119	              </ul>
120	            )}
121	          </li>
122	        );
123	      })}
124	    </ul>
125	  );
126	}
127	
128	/** Whether every point that must be made is made, for the button that waits on it. */
129	export function checklistDone(items: ChecklistItem[], pack: Pack, state: RunState, ticked: Set<string>, settling?: Settling): boolean {
130	  const points = items.map(pointOf);
131	  return allMade(
132	    points,
133	    points.map((p) => (p.shows ? evidenceFor(pack, state, p.shows) : [])),
134	    ticked,
135	    settling,
136	  );
137	}
138	
